(async () => {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('INPUT_PATH env var is required');
  if (!outputPath) throw new Error('OUTPUT_PATH env var is required');
  try { await fs.promises.access(inputPath, fs.constants.R_OK); }
  catch { throw new Error(`Input file not accessible: ${inputPath}`); }
  const width = process.env.WIDTH ? parseInt(process.env.WIDTH, 10) : undefined;
  const height = process.env.HEIGHT ? parseInt(process.env.HEIGHT, 10) : undefined;
  globalThis._sharpInput = { inputPath, outputPath, width, height };
})();

(async () => {
  const { inputPath, outputPath, width, height } = globalThis._sharpInput;
  const sharpMod = await import('sharp');
  const sharp = sharpMod.default || sharpMod;
  let pipeline = sharp(inputPath);
  const resizeOpts = {};
  if (width) resizeOpts.width = width;
  if (height) resizeOpts.height = height;
  if (Object.keys(resizeOpts).length) pipeline = pipeline.resize(resizeOpts);
  await pipeline.toFile(outputPath);
  globalThis._sharpResult = { outputPath };
})();

(async () => {
  const { outputPath } = globalThis._sharpResult || {};
  if (!outputPath) throw new Error('outputPath not set');
  console.log(JSON.stringify({ output_path: outputPath }));
})();
